using System;using System.Collections.Generic;public class Solution{public IList<IList<int>> ThreeSum(int[]a){Array.Sort(a);var o=new List<IList<int>>();for(int i=0;i+2<a.Length;i++){if(i>0&&a[i]==a[i-1])continue;int l=i+1,r=a.Length-1;while(l<r){long s=(long)a[i]+a[l]+a[r];if(s<0)l++;else if(s>0)r--;else{o.Add(new List<int>{a[i],a[l],a[r]});int x=a[l],y=a[r];while(l<r&&a[l]==x)l++;while(l<r&&a[r]==y)r--;}}}return o;}}
